#!/usr/bin/env bash
set -eo pipefail
export HOME=/root
APP=/opt/mesocyclonic-viewer
cd "$APP"
mkdir -p scripts/model tests
echo '' | base64 -d > 'scripts/model/train.py'
echo 'escrito: scripts/model/train.py ('$(wc -l < 'scripts/model/train.py')' lineas)'
echo '' | base64 -d > 'tests/test_model_dataset.py'
echo 'escrito: tests/test_model_dataset.py ('$(wc -l < 'tests/test_model_dataset.py')' lineas)'
echo '' | base64 -d > 'scripts/model/build_dataset.py'
echo 'escrito: scripts/model/build_dataset.py ('$(wc -l < 'scripts/model/build_dataset.py')' lineas)'
echo '' | base64 -d > 'scripts/model/score.py'
echo 'escrito: scripts/model/score.py ('$(wc -l < 'scripts/model/score.py')' lineas)'
echo TRANSFER_DONE
